def transform(grid):
    from collections import Counter
    a=[row[:] for row in grid]
    bg=Counter(x for row in a for x in row).most_common(1)[0][0]
    pts=[(r,c) for r,row in enumerate(a) for c,v in enumerate(row) if v!=bg]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    # Complete the outer rectangular frame.
    for c in range(c0,c1+1):
        if a[r0][c]==bg:a[r0][c]=2
        if a[r1][c]==bg:a[r1][c]=2
    for r in range(r0,r1+1):
        if a[r][c0]==bg:a[r][c0]=2
        if a[r][c1]==bg:a[r][c1]=2
    # Fill short gaps in any aligned interior strokes as well.
    colors=set(x for row in a for x in row if x!=bg)
    for color in colors:
        for r in range(len(a)):
            cs=[c for c,v in enumerate(a[r]) if v==color]
            for x,y in zip(cs,cs[1:]):
                if y-x-1<=4:
                    for c in range(x+1,y):
                        if a[r][c]==bg:a[r][c]=2
        for c in range(len(a[0])):
            rs=[r for r in range(len(a)) if a[r][c]==color]
            for x,y in zip(rs,rs[1:]):
                if y-x-1<=4:
                    for r in range(x+1,y):
                        if a[r][c]==bg:a[r][c]=2
    return a

